use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut i: int = 0
    let n: int = keys.len() as int
    while i < n {
        if keys[i as usize] == k {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut cap: int = 1
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let i = find(keys, k)
            if i >= 0 {
                keys.remove(i as usize)
                vals.remove(i as usize)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() as int > cap {
                let last = keys.len() - 1
                let ek = keys[last]
                keys.remove(last)
                vals.remove(last)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let i = find(keys, k)
            if i < 0 {
                println("-1")
            } else {
                let v = vals[i as usize]
                keys.remove(i as usize)
                vals.remove(i as usize)
                keys.insert(0, k)
                vals.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut j = 0
                while j < keys.len() {
                    if j > 0 {
                        s = s + " "
                    }
                    s = s + keys[j].to_string()
                    j += 1
                }
                println("${s}")
            }
        }
    }
}

